    source: 'https://react.dev/reference/react/useDeferredValue',
    interview: { question: 'useDeferredValue와 Debounce의 차이는 무엇인가요?', answer: 'Debounce는 여러 호출을 시간 기준으로 모으지만 useDeferredValue는 React 렌더가 새 값을 반영할 우선순위를 조절한다. 기기와 작업 상황에 따라 따라오는 시점이 달라 고정 지연을 설정하지 않는다. 요청 빈도 제한이 목적이면 별도 정책이 필요하고 오래된 결과임을 사용자에게 표시해야 한다.', followUp: '목록 컴포넌트가 매번 즉시 다시 렌더된다면 지연 값만 추가하는 것으로 입력 지연이 해결될까요?' },
    codeLanguage: 'jsx', code: "import { useState, useDeferredValue } from 'react';\nimport SlowResults from './SlowResults'; // 내부 렌더 비용을 분리한 memo 컴포넌트\nfunction Search() {\n  const [query, setQuery] = useState('');\n  const deferred = useDeferredValue(query);\n  return <>\n    <input aria-label=\"검색\" value={query}\n      onChange={event => setQuery(event.target.value)} />\n    <div style={{ opacity: query === deferred ? 1 : 0.6 }}>\n      <SlowResults query={deferred} />\n    </div>\n  </>;\n}",
