    codeLanguage: 'jsx', code: "import { useOptimistic, useState, useTransition } from 'react';\nfunction LikeButton({ liked, onSave }) {\n  const [optimistic, setOptimistic] = useOptimistic(liked);\n  const [pending, startTransition] = useTransition();\n  const [error, setError] = useState('');\n  return <>\n    <button disabled={pending} aria-pressed={optimistic} onClick={() => {\n      startTransition(async () => {\n        setError(''); setOptimistic(true);\n        try { await onSave(true); } // 성공 시 부모의 liked도 갱신\n        catch { setError('저장에 실패했습니다.'); }\n      });\n    }}>좋아요</button>\n    {error && <p role=\"alert\">{error}</p>}\n  </>;\n}",
